create table if not exists public.compras (id uuid primary key default gen_random_uuid(),sede_id uuid not null references public.sedes(id) on delete restrict,numero text not null,proveedor_nombre text not null default '',proveedor_participante_id uuid,estado text not null default 'borrador',moneda text not null default 'PEN',fecha_emision date not null default current_date,fecha_entrega date,subtotal numeric not null default 0 check (subtotal >= 0),impuestos numeric not null default 0 check (impuestos >= 0),total numeric not null default 0 check (total >= 0),notas text not null default '',creado_por uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(sede_id,numero),constraint compras_estado_check check (estado in ('borrador','ordenada','parcial','recibida','cancelada')));
create table if not exists public.compra_detalles (id uuid primary key default gen_random_uuid(),compra_id uuid not null references public.compras(id) on delete cascade,material_id uuid not null references public.inventario(id) on delete restrict,descripcion text not null default '',cantidad numeric not null check (cantidad > 0),cantidad_recibida numeric not null default 0 check (cantidad_recibida >= 0),unidad text not null default '',costo_unitario numeric not null check (costo_unitario >= 0),impuesto numeric not null default 0 check (impuesto >= 0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint compra_detalle_recibido_check check (cantidad_recibida <= cantidad));
create index if not exists compras_sede_fecha_idx on public.compras(sede_id,fecha_emision desc);
create index if not exists compra_detalles_compra_idx on public.compra_detalles(compra_id);
alter table public.compras enable row level security; alter table public.compra_detalles enable row level security;
drop policy if exists "compras leer sede" on public.compras; create policy "compras leer sede" on public.compras for select to authenticated using (ve_sede(auth.uid(),sede_id));
drop policy if exists "compras gestionar admin" on public.compras; create policy "compras gestionar admin" on public.compras for all to authenticated using (es_admin(auth.uid()) and ve_sede(auth.uid(),sede_id)) with check (es_admin(auth.uid()) and ve_sede(auth.uid(),sede_id));
drop policy if exists "compra detalles leer sede" on public.compra_detalles; create policy "compra detalles leer sede" on public.compra_detalles for select to authenticated using (exists(select 1 from public.compras c where c.id=compra_id and ve_sede(auth.uid(),c.sede_id)));
drop policy if exists "compra detalles gestionar admin" on public.compra_detalles; create policy "compra detalles gestionar admin" on public.compra_detalles for all to authenticated using (exists(select 1 from public.compras c where c.id=compra_id and es_admin(auth.uid()) and ve_sede(auth.uid(),c.sede_id))) with check (exists(select 1 from public.compras c where c.id=compra_id and es_admin(auth.uid()) and ve_sede(auth.uid(),c.sede_id)));
create or replace function public.recibir_compra(_compra_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare c record; d record; v_rec numeric; v_total numeric:=0; begin select * into c from public.compras where id=_compra_id for update; if not found then raise exception 'Compra no encontrada'; end if; if not public.es_admin(auth.uid()) or not public.ve_sede(auth.uid(),c.sede_id) then raise exception 'No tienes permisos para recibir esta compra'; end if; if c.estado='cancelada' then raise exception 'No se puede recibir una compra cancelada'; end if; for d in select * from public.compra_detalles where compra_id=_compra_id for update loop v_rec:=d.cantidad-d.cantidad_recibida; if v_rec>0 then insert into public.inventario_movimientos(material_id,usuario_id,tipo,cantidad,motivo,referencia_externa,costo_unitario) values(d.material_id,auth.uid(),'entrada',v_rec,'Recepción de compra',c.numero,d.costo_unitario); update public.compra_detalles set cantidad_recibida=d.cantidad,updated_at=now() where id=d.id; v_total:=v_total+v_rec; end if; end loop; update public.compras set estado='recibida',updated_at=now() where id=_compra_id; return jsonb_build_object('compra_id',_compra_id,'cantidad_recibida',v_total); end; $$;
revoke execute on function public.recibir_compra(uuid) from public,anon; grant execute on function public.recibir_compra(uuid) to authenticated;